class TestLoptInitExports:
    def test_lopt_available_is_bool(self):
        assert isinstance(LOPT_AVAILABLE, bool)

    def test_lopt_parallel_tokenizer_is_class(self):
        assert isinstance(LoptParallelTokenizer, type)

